CREATE OR REPLACE FUNCTION public.edit_employee(_id uuid,_nombre text,_username text,_activo boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_manager() THEN RAISE EXCEPTION 'Solo encargado'; END IF; IF _id=auth.uid() AND NOT _activo THEN RAISE EXCEPTION 'No puede desactivarse'; END IF; IF length(trim(_nombre)) NOT BETWEEN 1 AND 100 OR _username !~ '^[a-z0-9._-]{3,40}$' THEN RAISE EXCEPTION 'Datos inválidos'; END IF; IF EXISTS(SELECT 1 FROM profiles WHERE username=_username AND id<>_id) THEN RAISE EXCEPTION 'Usuario duplicado'; END IF; UPDATE auth.users SET email=_username||'@fichaje.local' WHERE id=_id; UPDATE public.profiles SET nombre=trim(_nombre),username=_username,activo=_activo WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.edit_employee(uuid,text,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.edit_employee(uuid,text,text,boolean) TO authenticated;
REVOKE UPDATE ON public.profiles FROM authenticated; REVOKE UPDATE(nombre,activo) ON public.profiles FROM authenticated;